      mu: days[today], streak: streak, bars: bars, board: board, sheet: sheetStars[board], sheetT: sheetStars[board + '_t'],
      stackStars: sum(this.read('raf_games_stars_stack', {}), 10), stackBest: Number(this.read('raf_games_stack_best', 0)) || 0,
      nailStars: sum(this.read('raf_games_stars_nail', {}), 9), sheetAll: sum(sheetStars, 40),
      levelStars: sum(this.read('raf_games_stars_level', {}), 10),
