      const off = offLeft ? { x: cur.x, w: last.x - cur.x } : { x: R, w: cur.x + cur.w - R };
      g.falling.push({ x: off.x, w: off.w, y: level * T, vx: offLeft ? -180 : 180, vy: 160, rot: 0, vr: offLeft ? -2.4 : 2.4, sp: cur.sp, seed: cur.seed });
